/**
 * Where a body's owner link is read, and how it may be written (#622,
 * under PRD #599). Session rule 1 tells a session to sign a body or a post
 * with its link alone on the line just above the Claude Code footer, and a
 * body may end in either footer: the comment footer
 * `_Generated by [Claude Code](https://claude.ai/code)_` or the PR-style
 * line `🤖 Generated with [Claude Code](https://claude.com/claude-code)`.
 *
 * A link alone on its line counts where nothing below it is anything but
 * blank lines, rules and footer lines. Its line may also carry whitespace,
 * angle brackets, a Markdown link to the session URL, emphasis, a trailing
 * full stop, or a fixed label. `postedBy` reads a post's signature by the
 * same rule, and the writers, `relinkSession` and `unlinkSession`, replace
 * or remove exactly the link `sessionNamedIn` reads.
 */

import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import { isSessionPost, ownSessionPost, postedBy, relayedBody, relinkSession, sessionNamedIn, unlinkSession, unsignedSessionBody } from '../dispatch/webhook/subscribe.mjs';

const OWNER = 'https://claude.ai/code/session_01OWNERAAA';
const OTHER = 'https://claude.ai/code/session_01OTHERBBB';
const PR_FOOTER = '🤖 Generated with [Claude Code](https://claude.com/claude-code)';
const COMMENT_FOOTER = '---\n_Generated by [Claude Code](https://claude.ai/code)_';

/** Each way of writing the owner's line, with `L` for the session URL. */
const WRITTEN: Record<string, (link: string) => string> = {
  bare: (l) => l,
  'whitespace around it': (l) => `  ${l}\t `,
  'angle brackets': (l) => `<${l}>`,
  'a Markdown link with the URL as its text': (l) => `[${l}](${l})`,
  'a Markdown link with words as its text': (l) => `[This session](${l})`,
  'underscore emphasis': (l) => `_${l}_`,
  'star emphasis': (l) => `*${l}*`,
  'strong emphasis': (l) => `**${l}**`,
  'a trailing full stop': (l) => `${l}.`,
  'emphasis and a full stop': (l) => `_${l}_.`,
  'a Session: label': (l) => `Session: ${l}`,
  'a Claude-Session: label': (l) => `Claude-Session: ${l}`,
  'a label in lower case': (l) => `claude-session: ${l}`,
  'a label in upper case, angle brackets': (l) => `SESSION: <${l}>`,
  'a bold label': (l) => `**Session:** ${l}`,
  'a label, a Markdown link and a full stop': (l) => `Session: [link](${l}).`,
};

/** Each place the owner's line may sit, with `W` for the line as written. */
const PLACED: Record<string, (written: string) => string> = {
  'just above the PR-style footer': (w) => `The spec.\n\n${w}\n\n${PR_FOOTER}`,
  'just above the comment footer': (w) => `The spec.\n\n${w}\n\n${COMMENT_FOOTER}`,
  'just under the PR-style footer': (w) => `The spec.\n\n${PR_FOOTER}\n\n${w}`,
  'just under the comment footer': (w) => `The spec.\n\n${COMMENT_FOOTER}\n\n${w}`,
  'between the PR-style footer and the comment footer': (w) => `The spec.\n\n${PR_FOOTER}\n\n${w}\n\n${COMMENT_FOOTER}`,
  'between the comment footer and the PR-style footer': (w) => `The spec.\n\n${COMMENT_FOOTER}\n\n${w}\n\n${PR_FOOTER}`,
  'on the last line': (w) => `The spec.\n\n${w}`,
  'on the last line, a rule and blank lines below it': (w) => `The spec.\n\n${w}\n\n***\n\n`,
  'above both footers, the PR-style one first': (w) => `The spec.\n\n${w}\n\n${PR_FOOTER}\n\n${COMMENT_FOOTER}\n`,
};

/** Each footer that ends a post, for postedBy. */
const POST_FOOTERS: Record<string, string> = { 'the comment footer': COMMENT_FOOTER, 'the PR-style footer': PR_FOOTER };

describe('a body\'s owner link: each placement, each way of writing it, and the write that pairs with each read', () => {
  for (const [placement, place] of Object.entries(PLACED)) {
    for (const [form, write] of Object.entries(WRITTEN)) {
      const body = place(write(OWNER));
      test(`${placement}, written as ${form}: read, replaced and removed`, () => {
        assert.equal(sessionNamedIn(body), OWNER, body);
        const relinked = relinkSession(body, OTHER);
        assert.equal(sessionNamedIn(relinked), OTHER, relinked);
        assert.ok(!relinked.includes(OWNER), `the old link is gone: ${relinked}`);
        assert.equal(relinked, place(write(OTHER)), 'the line keeps the way it was written');
        const unlinked = unlinkSession(body);
        assert.equal(sessionNamedIn(unlinked), null, unlinked);
        assert.ok(!unlinked.includes(OWNER), `the link is gone: ${unlinked}`);
        assert.ok(unlinked.startsWith('The spec.'), unlinked);
        assert.equal(unlinked.includes('[Claude Code]'), body.includes('[Claude Code]'), 'the footers stay');
      });
    }
  }

  test('a link under the last footer is read as today, words around it or not', () => {
    assert.equal(sessionNamedIn(`The spec.\n\n${PR_FOOTER}\n\nBy ${OWNER} for now`), OWNER);
    assert.equal(sessionNamedIn(`The spec.\n\n${PR_FOOTER}\n\n${OTHER}\n\n${OWNER}`), OWNER, 'the last one');
  });

  test('a link above every footer and one under the last: the one under it is the owner', () => {
    assert.equal(sessionNamedIn(`The spec.\n\n${OTHER}\n\n${PR_FOOTER}\n\n${OWNER}`), OWNER);
  });

  test('on a person\'s issue the editor\'s link above the PR-style footer goes with the footer it signed', () => {
    const out = unlinkSession(`A person's spec.\n\n${OWNER}\n\n${PR_FOOTER}`, { footer: true });
    assert.equal(out, 'A person\'s spec.');
    assert.equal(unsignedSessionBody(out), false);
  });

  test('a relink replaces the owner link, not a longer id it starts in the Markdown link\'s text', () => {
    const body = `The spec.\n\n[${OWNER}X](${OWNER})\n\n${PR_FOOTER}`;
    assert.equal(relinkSession(body, OTHER), `The spec.\n\n[${OWNER}X](${OTHER})\n\n${PR_FOOTER}`);
  });

  test('a last line of many brackets is read in linear time, since a stranger\'s summons is read before its writer is judged', () => {
    const started = Date.now();
    assert.equal(sessionNamedIn(`The spec.\n\n${'['.repeat(60000)}`), null);
    assert.equal(postedBy(`Fixed.\n\n${'['.repeat(60000)}\n\n${PR_FOOTER}`), null);
    assert.ok(Date.now() - started < 2000, `took ${Date.now() - started}ms`);
  });

  test('a body naming nobody gets the new owner appended, and a relink of what it wrote reads back', () => {
    const relinked = relinkSession(`The spec.\n\nSee ${OTHER} for the history.\n\n${PR_FOOTER}`, OWNER);
    assert.equal(sessionNamedIn(relinked), OWNER);
    assert.ok(relinked.includes(`See ${OTHER} for the history.`), 'a citation stays');
  });
});

describe('a body\'s owner link: what still does not count', () => {
  const nobody: Record<string, string> = {
    'a link inside a quote above the footer': `The spec.\n\n> ${OWNER}\n\n${PR_FOOTER}`,
    'a quoted signature and footer': `The spec.\n\n> Fixed.\n>\n> ${OWNER}\n>\n> ${PR_FOOTER}`,
    'a link with words before it': `The spec.\n\nSee ${OWNER}\n\n${PR_FOOTER}`,
    'a link with words after it': `The spec.\n\n${OWNER} stalled.\n\n${PR_FOOTER}`,
    'a link after a label that is not one of the fixed ones': `The spec.\n\nRelated: ${OWNER}\n\n${PR_FOOTER}`,
    'a Markdown link to a session with words around it': `The spec.\n\nSee [the session](${OWNER}) for more.\n\n${COMMENT_FOOTER}`,
    'a link with a line of text below it': `The spec.\n\n${OWNER}\n\nMore of the spec.\n\n${PR_FOOTER}`,
    'a link with a quote below it': `The spec.\n\n${OWNER}\n\n> A quote.\n\n${PR_FOOTER}`,
    'a link with a list item below it': `The spec.\n\n${OWNER}\n\n- an item\n\n${COMMENT_FOOTER}`,
    'a line that only mentions Claude Code below it': `The spec.\n\n${OWNER}\n\nBuilt with [Claude Code](https://claude.ai/code) today.`,
    'two links on one line': `The spec.\n\n${OTHER} ${OWNER}\n\n${PR_FOOTER}`,
  };
  for (const [what, body] of Object.entries(nobody)) {
    test(`${what} names nobody, and the writers leave it be`, () => {
      assert.equal(sessionNamedIn(body), null, body);
      assert.equal(unlinkSession(body), body);
      assert.ok(relinkSession(body, OTHER).startsWith(body.trimEnd()), 'a relink appends, and changes nothing above');
    });
  }

  test('a body trust.relay masks names nobody, however it is signed', () => {
    for (const body of [`The spec.\n\n${OWNER}\n\n${PR_FOOTER}`, `The spec.\n\nSession: <${OWNER}>.\n\n${COMMENT_FOOTER}`]) {
      assert.equal(sessionNamedIn(relayedBody({ association: 'NONE', body }, ['OWNER', 'MEMBER'])), null, body);
      assert.equal(sessionNamedIn(relayedBody({ association: 'MEMBER', body }, ['OWNER', 'MEMBER'])), OWNER, body);
    }
  });
});

describe('postedBy reads a post\'s signature by the same rule', () => {
  for (const [shape, footer] of Object.entries(POST_FOOTERS)) {
    for (const [form, write] of Object.entries(WRITTEN)) {
      test(`just above ${shape}, written as ${form}`, () => {
        assert.equal(postedBy(`Fixed.\n\n${write(OWNER)}\n\n${footer}`), OWNER);
      });
    }
    test(`just under ${shape}, as today`, () => {
      assert.equal(postedBy(`Fixed.\n\n${footer}\n\n${OWNER}`), OWNER);
    });
    test(`between ${shape} and the other footer`, () => {
      const other = footer === PR_FOOTER ? COMMENT_FOOTER : PR_FOOTER;
      assert.equal(postedBy(`Fixed.\n\n${footer}\n\n${OWNER}\n\n${other}`), OWNER);
    });
    test(`a citation above ${shape}, or a quoted post, is not the poster`, () => {
      assert.equal(postedBy(`Handed to ${OTHER}\n\n${footer}`), null, 'words before the link');
      assert.equal(postedBy(`Fixed: ${OTHER}\n\n${footer}`), null, 'a label that is not one of the fixed ones');
      assert.equal(postedBy(`${OTHER}\n\nFixed.\n\n${footer}`), null, 'a line of text below the link');
      assert.equal(postedBy(`> Fixed.\n>\n> ${OTHER}\n>\n> ${footer.replace('\n', '\n> ')}\n\nNot fixed.`), null, 'a quoted post');
    });
  }

  test('a post postedBy reads as signed is a session\'s own post, so it summons nobody and starts no takeover', () => {
    for (const [shape, footer] of Object.entries(POST_FOOTERS)) {
      for (const [form, write] of Object.entries(WRITTEN)) {
        const post = `@claude look at this.\n\n${write(OWNER)}\n\n${footer}`;
        assert.equal(postedBy(post), OWNER, `${shape}, ${form}`);
        assert.equal(ownSessionPost(post), true, `${shape}, ${form}`);
        assert.equal(isSessionPost(post), true, `${shape}, ${form}`);
      }
    }
  });

  test('a post with no Claude Code footer is no session\'s, though a link ends it: a person pasting a session\'s link is still heard by it', () => {
    assert.equal(postedBy(`@claude this one stalled, can you look?\n\n${OWNER}`), null);
    assert.equal(postedBy(`Session: ${OWNER}`), null);
  });
});
